-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN
  -- propranolol (CIS 65135519)
  m := pg_temp.jp_matrice_by_norm('propranolol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Médicaments bêtabloquants, non-sélectifs (bêtabloquants), code ATC : C07AA05.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Angine de poitrine.', 'Hypertension artérielle.', 'Prévention à long terme contre une récidive d’infarctus du myocarde après avoir récupéré suite à un infarctus aigu du myocarde.', 'Cardiomyopathie obstructive hypertrophique.', 'Tremblement essentiel.', 'Arythmie cardiaque supraventriculaire.', 'Arythmies cardiaques ventriculaires.', 'Hyperthyroïdie et thyrotoxicose.', 'Phéochromocytome (avec un alpha-bloquant).', 'Migraine.', 'Prévention des hémorragies gastro-intestinales hautes chez les patients présentant une hypertension portale et des varices œsophagiennes.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients listés dans la rubrique 6.1.', 'Insuffisance cardiaque non contrôlée par le traitement.', 'Maladie du sinus /bloc sino-auriculaire.', 'Antécédents de bronchospasme ou d’asthme bronchique, bronchopneumopathie chronique obstructive.', 'Acidose métabolique.', 'Blocs auriculoventriculaires des second et troisième degrés.', 'Prédisposition à l''hypoglycémie (comme après un jeûne ou en cas d''anomalie de réponse aux hypoglycémies).', 'Choc cardiogénique.', 'Phéochromocytome non traité.', 'Bradycardie sévère.', 'Hypotension artérielle sévère', 'Troubles artériels périphériques sévères']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Propranolol, comme pour les autres bêtabloquants :', 'bien que contre-indiqué en cas d''insuffisance cardiaque non contrôlée (voir rubrique 4.3), il peut être utilisé chez les patients dont les signes d''insuffisance cardiaque ont été contrôlés.', 'La prudence doit être exercée chez les patients dont la réserve cardiaque est diminuée ;', 'Cela peut entraîner une hypotension sévère, une bradycardie et une insuffisance cardiaque.', 'Ni le bétabloquant, ni l’inhibiteur des canaux calciques ne doit être administré par voie intraveineuse dans les 48 heures suivant l''arrêt de l''autre.', 'bien que contre-indiqué dans les troubles circulatoires artériels périphériques sévères (voir rubrique 4.3), peut également aggraver les troubles circulatoires artériels périphériques moins sévères ;', 'en raison de son effet négatif sur le temps de conduction, il faut faire preuve de prudence s''il est administré à des patients atteints d''un bloc auriculoventriculaire de premier degré ;', 'peut masquer/modifier les signes annonciateurs d’une hypoglycémie (en particulier, la tachycardie).', 'Des hypoglycémies sévères associées à la prise de propranolol ont rarement conduit à des crises convulsives et/ou un coma.', 'La prudence est recommandée chez les patients diabétiques qui reçoivent un traitement hypoglycémiant concomitant.', 'Le propranolol peut prolonger la réponse hypoglycémique à l’insuline (voir rubrique 4.3) ;', 'peut masquer les signes d’une thyrotoxicose ;']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations non recommandées', 'Cela peut provoquer une hypotension grave et une bradycardie.', 'Il convient d’éviter l’association avec le propranolol, en particulier chez les patients qui présentent une insuffisance cardiaque.', 'L''utilisation concomitante d''agents sympathomimétiques, par exemple l''adrénaline, peut contrecarrer l''effet des bêta-bloquants.', '+ Bronchodilatateurs bêta-agonistes', 'Les bétabloquants non cardiosélectifs s’opposant aux effets bronchodilatateurs des bronchodilatateurs bêta-agonistes, le propranolol est contre-indiqué chez les patients asthmatiques (voir rubrique 4.3).', '+ Fingolimod', 'Potentialisation des effets bradycardisants avec possibilité d’issue fatale.', 'Le traitement par fingolimod ne doit pas être instauré chez les patients recevant des bétabloquants.', 'En cas d’association, il est recommandé de procéder à une surveillance appropriée pendant l’instauration du traitement, au moins jusqu’au lendemain.', '+ Barbituriques', 'Les barbituriques diminuent les concentrations plasmatiques et les effets des bétabloquants.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥ 1/10) ; fréquent (≥ 1/100 à 1/10) ; peu fréquent (≥ 1/1000 à ; rare (≥ 1/10 000 à ; très rare ( 1/10 000) ; fréquence indéterminée (ne peut pas être estimée sur la base des données di', 'Très fréquent', 'Fréquent', 'Thrombocytopénie']);

  -- pindolol (CIS 61252667)
  m := pg_temp.jp_matrice_by_norm('pindolol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : béta-bloquant non sélectif, code ATC : C07AA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle.', 'Prophylaxie des crises d''angor d''effort.', 'Signes fonctionnels des cardiomyopathies obstructives.', 'Manifestations cardiovasculaires des hyperthyroïdies.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Insuffisance cardiaque non contrôlée par le traitement.', 'Choc cardiogénique.', 'Blocs auriculo-ventriculaires des second et troisième degrés non appareillés.', 'Angor de Prinzmetal.', 'Maladie du sinus (y compris bloc sino-auriculaire).', 'Bradycardie (Phénomène de Raynaud et troubles artériels périphériques.', 'Phéochromocytome non traité.', 'Hypotension.', 'Antécédent de réaction anaphylactique.', 'Association à la floctafénine ou au sultopride (voir rubrique 4.5).', 'Ce médicament est généralement déconseillé au cours de l''allaitement.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'En raison de la présence de lactose, ce médicament est contre-indiqué en cas de galactosémie congénitale, de syndrome de malabsorption du glucose et du galactose ou de déficit en lactase.', 'L’association de ces médicaments avec du diltiazem, du vérapamil, du bépridil est déconseillée (cf rubrique 4.5).', 'Ne jamais interrompre brutalement le traitement chez les angineux : l''arrêt brusque peut entraîner des troubles du rythme graves, un infarctus du myocarde ou une mort subite.', 'Précautions d''emploi', 'Arrêt du traitement : le traitement ne doit pas être interrompu brutalement, en particulier chez les patients présentant une cardiopathie ischémique.', 'La posologie doit être diminuée progressivement, c''est-à-dire idéalement sur une à deux semaines, en commençant en même temps, si nécessaire, le traitement substitutif, pour éviter une aggravation de l''angor.', 'Insuffisance cardiaque : chez l''insuffisant cardiaque contrôlé par le traitement et en cas de nécessité, le pindolol sera administré à très faibles doses progressivement croissantes et sous surveillance médicale stricte.', 'Bradycardie : si la fréquence s''abaisse au-dessous de 50-55 pulsations par minute au repos et que le patient présente des symptômes liés à la bradycardie, la posologie doit être diminuée.', 'Bloc auriculo-ventriculaire du premier degré : étant donné leur effet dromotrope négatif, les bêta-bloquants doivent être administrés avec prudence aux patients présentant un bloc auriculo-ventriculaire du premier degré.', 'Phéocromocytome : l''utilisation des bêta-bloquants dans le traitement de l''hypertension due au phéocromocytome traité nécessite une surveillance étroite de la pression artérielle.', 'Sujet âgé : chez le sujet âgé, le respect absolu des contre-indications est impératif.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['De nombreux médicaments peuvent entrainer une bradycardie.', 'C’est le cas des antiarythmiques de classe Ia, des bêta-bloquants, de certains antiarythmiques de classe III, de certains antagonistes du calcium, des digitaliques, de la pilocarpine anticholinestérasiques, etc.', 'Associations contre-indiquées', '+ Floctafénine', 'En cas de choc ou d''hypotension dus à la floctafénine, réduction des réactions cardiovasculaires de compensation par les bêta-bloquants.', '+ Sultopride', 'Risque majoré de troubles du rythme ventriculaires, notamment de torsades de pointes.', 'Associations déconseillées', '+ Bépridil', 'Une telle association ne doit se faire que sous surveillance clinique et ECG étroite, en particulier chez le sujet âgé ou en début de traitement.', '+ Diltiazem', 'Troubles de l’automatisme (bradycardie excessive, arrêt sinusal), troubles de la conduction sino-auriculaire et auriculo-ventriculaire et défaillance cardiaque.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables sont classés par fréquence, comme suit : très fréquent (³ 1/10) ; fréquent (³ 1/100, ³ 1/1000, ³ 1/10 000, Affections cardiaques']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Insuffisance cardiaque : chez l''insuffisant cardiaque contrôlé par le traitement et en cas de nécessité, le pindolol sera administré à très faibles doses progressivement croissantes et sous surveillance médicale stricte.', 'Phéocromocytome : l''utilisation des bêta-bloquants dans le traitement de l''hypertension due au phéocromocytome traité nécessite une surveillance étroite de la pression artérielle.']);

  -- nadolol (CIS 62092895)
  m := pg_temp.jp_matrice_by_norm('nadolol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Bêta-bloquant non sélectif, code ATC : C07AA12');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle.', 'Prophylaxie des crises d''angor d''effort.', 'Signes fonctionnels des cardiomyopathies obstructives.', 'Manifestations cardiovasculaires des hyperthyroïdies.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité au nadolol ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Asthme et broncho-pneumopathies chroniques obstructives.', 'Insuffisance cardiaque non contrôlée par le traitement.', 'Choc cardiogénique.', 'Blocs auriculo-ventriculaires des seconds et troisièmes degrés non appareillés.', 'Angor de Prinzmétal.', 'Maladie du sinus (y compris bloc sino-auriculaire).', 'Bradycardie (', 'Phénomène de Raynaud et troubles artériels périphériques.', 'Phéochromocytome non traité.', 'Hypotension.', 'Antécédent de réaction anaphylactique.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Ne jamais interrompre brutalement le traitement chez les angineux : l''arrêt brusque peut entraîner des troubles du rythme graves, un infarctus du myocarde ou une mort subite.', 'Précaution d’emploi', 'Arrêt du traitement', 'Le traitement ne doit pas être interrompu brutalement, en particulier chez les patients présentant une cardiopathie ischémique.', 'La posologie doit être diminuée progressivement, c''est-à-dire idéalement sur une à deux semaines, en commençant en même temps, si nécessaire, le traitement substitutif, pour éviter une aggravation de l''angor.', 'Insuffisance cardiaque', 'Chez l''insuffisant cardiaque contrôlé par le traitement et en cas de nécessité, le nadolol sera administré à très faibles doses progressivement croissantes et sous surveillance médicale stricte.', 'Bradycardie', 'Si la fréquence s''abaisse au-dessous de 50-55 pulsations par minute au repos et que le patient présente des symptômes liés à la bradycardie, la posologie doit être diminuée.', 'Bloc auriculo-ventriculaire du premier degré', 'Etant donné leur effet dromotrope négatif, les bêta-bloquants doivent être administrés avec prudence aux patients présentant un bloc auriculo-ventriculaire du premier degré.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments bradycardisants', 'De nombreux médicaments peuvent entraîner une bradycardie.', 'Un arrêt sinusal peut survenir lorsque les bêta-bloquants, y compris CORGARD, sont utilisés en association avec d''autres médicaments connus pour induire un arrêt sinusal (voir rubrique 4.8.)', 'Associations déconseillées', '+ Diltiazem', 'Troubles de l''automatisme (bradycardie excessive, arrêt sinusal), troubles de la conduction sino-auriculaire et auriculo-ventriculaire et défaillance cardiaque.', 'Une telle association ne doit se faire que sous surveillance clinique et ECG étroite, en particulier chez le sujet âgé ou en début de traitement.', 'Une augmentation du risque de dépression a été rapportée lorsque les bêta-bloquants sont co-administrés avec le diltiazem (voir rubrique 4.8 Effets indésirables).', '+ Vérapamil', 'Troubles de l''automatisme (bradycardie excessive, arrêt sinusal), trouble de la conduction sino-auriculaire et auriculo-ventriculaire et défaillance cardiaque.', '+ Fingolimod', 'Potentialisation des effets bradycardisants pouvant avoir des conséquences fatales.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Au plan clinique', 'Les plus fréquemment rapportés :', 'asthénie,', 'refroidissement des extrémités,', 'bradycardie, sévère le cas échéant,', 'troubles digestifs (gastralgies, nausées, vomissements),']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Chez l''insuffisant cardiaque contrôlé par le traitement et en cas de nécessité, le nadolol sera administré à très faibles doses progressivement croissantes et sous surveillance médicale stricte.']);

  -- labetalol (CIS 61308023)
  m := pg_temp.jp_matrice_by_norm('labetalol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Alpha et bêtabloquants, code ATC: C07AG01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension sévère, notamment l’hypertension sévère pendant la grossesse lorsqu’il est essentiel de normaliser rapidement la pression artérielle.', 'Peut être utilisé pour atteindre une hypotension contrôlée pendant une anesthésie.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1', 'Chez les patients asthmatiques ou ayant des antécédents de maladie pulmonaire obstructive', 'Blocs cardiaques du deuxième ou troisième degrés (sauf si un stimulateur cardiaque est en place), chocs cardiogéniques et tout autre trouble associé à une hypotension sévère et prolongée ou à une bradycardie sévère', 'Insuffisance cardiaque non compensée', 'Insuffisance cardiaque instable/non contrôlée', 'Maladie du sinus (notamment le bloc sino-atrial), sauf si un stimulateur cardiaque est en place', 'Angor de Prinzmetal', 'Dysfonction du nœud sinusal', 'Phéochromocytome non traité']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Pathologie hépatique', 'Il convient d’être prudent en cas de pathologie hépatique.', 'De très rares cas de lésions hépatocellulaires graves ont été rapportés en cas de traitement par labétalol.', 'La lésion hépatique est généralement réversible et a été observée tant après un traitement à court qu’après un traitement à long terme.', 'Cependant, une nécrose hépatique a été rapportée, dans certains cas avec une issue fatale.', 'Des analyses de laboratoire appropriées doivent être effectuées dès le premier signe ou symptôme de dysfonctionnement hépatique.', 'Si les analyses de laboratoire montrent une lésion hépatique ou si le patient présente un ictère, le traitement par labétalol doit être arrêté et ne doit pas être repris.', 'Il convient d’être prudent lorsque le labétalol est utilisé chez les patients présentant une insuffisance hépatique, car ces derniers métabolisent le labétalol plus lentement que les patients sans insuffisance hépatique.', 'Insuffisance rénale', 'Il est recommandé d’être prudent lorsque le labétalol est utilisé chez les patients présentant une insuffisance rénale sévère (FG = 15-29 ml/min/1,73m2).', 'Maladie vasculaire périphérique', 'Le labétalol doit être utilisé avec prudence chez les patients atteints de maladie vasculaire périphérique car cela peut exacerber leurs symptômes.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L''effet hypotenseur du labétalol peut être réduit lorsqu''il est utilisé en association avec des inhibiteurs de la prostaglandine synthétase (AINS, anti-inflammatoires non stéroïdiens).', 'Des ajustements posologiques peuvent donc être nécessaires.', 'Une synergie supplémentaire peut survenir avec d''autres agents antihypertenseurs.', 'Il a été démontré que le labétalol réduit l''absorption des radio-isotopes de la métaiodobenzylguanidine (MIBG).', 'Des précautions doivent donc être prises pour l''interprétation des résultats de la scintigraphie à la MIBG.', 'L''administration concomitante de labétalol et d''adrénaline peut entraîner une bradycardie et une hypertension (voir section 4.4 Mises en garde spéciales et précautions d''emploi).', 'Des précautions doivent être prises si le labétalol est utilisé en concomitance avec des agents antiarythmiques de classe I ou des antagonistes du calcium du type vérapamil.', 'Risque accru de dépression myocardique en association avec des antiarythmiques de classe I (par exemple disopyramide et quinidine) et de l''amiodarone (antiarythmiques de classe II).', 'En cas de passage d''un antagoniste du calcium à un bêtabloquant, ou inversement, un nouveau traitement par voie intraveineuse ne doit pas être initié avant au moins 48 heures après l''arrêt du traitement précédent.', 'Les glycosides digitaliques en association avec des bêtabloquants peuvent augmenter le temps de conduction auriculo-ventriculaire.', 'Le labétalol peut améliorer l''effet exercé par digoxine sur la réduction de la fréquence ventriculaire.', 'Des ajustements posologiques des antidiabétiques oraux et de l''insuline peuvent être nécessaires.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent']);

  -- timolol (CIS 66708726)
  m := pg_temp.jp_matrice_by_norm('timolol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique: ANTI-GLAUCOMATEUX ET MYOTIQUES, Bêta-bloquant, code ATC: S01ED01');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertonie intraoculaire.', 'Glaucome chronique à angle ouvert.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['pathologies respiratoires réactionnelles incluant asthme bronchique ou antécédents d’asthme bronchique, maladie pulmonaire obstructive chronique sévère, ou bronchopneumopathies chroniques obstructives,', 'insuffisance cardiaque manifeste ou non contrôlée par un traitement,', 'choc cardiogénique,', 'blocs auriculo-ventriculaires des second et troisième degrés non appareillés,', 'angor de Prinzmetal,', 'maladie du sinus,', 'bloc sino-auriculaire,', 'bradycardie sinusale (', 'maladie de Raynaud et troubles circulatoires périphériques,', 'phéochromocytome non traité,', 'hypotension artérielle,', 'hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1, ou à tout traitement ayant auparavant provoqué une réaction anaphylactique,']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Voie ophtalmique uniquement.', 'Après ouverture du bouchon, si le dispositif de sécurité du col du flacon est trop lâche, retirez-le avant d’utiliser ce produit.', 'Oculaires', 'Générales', 'La fréquence des effets indésirables systémiques après administration par voie ophtalmique locale est plus faible qu’après administration par voie générale.', 'Pour réduire l’absorption systémique, voir rubrique 4.2.', 'Dans le cas où le timolol en collyre est administré pour diminuer la pression intraoculaire chez les patients ayant un glaucome par fermeture de l''angle, un myotique doit être associé.', 'Autres bêta-bloquants', 'L''effet sur la pression intraoculaire ou les effets connus des bêta-bloquants par voie systémique peuvent être majorés en cas d''administration de timolol à des patients recevant déjà un bêta-bloquant systémique.', 'La réponse de ces patients devra être étroitement surveillée.', 'L''utilisation de deux bêta-bloquants topiques n''est pas recommandée (voir rubrique 4.5).', 'Maladies cornéennes']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Aucune étude d’interaction médicamenteuse spécifique n’a été réalisée avec timolol.', '1°) Autres collyres', 'Des mydriases ont été occasionnellement rapportées lorsque les bêta-bloquants ophtalmiques et l''adrénaline (épinéphrine) ont été utilisés de façon concomitante.', 'Une surveillance ophtalmologique est nécessaire en cas de traitement concomitant par un collyre contenant de l''adrénaline.', 'En cas d’utilisation de plusieurs médicaments topiques ophtalmiques, les administrations de médicament doivent être espacées d’au moins 5 minutes.', 'Les pommades ophtalmiques doivent être administrées en dernier.', '2°) Autres médicaments', 'Bien que les quantités de bêta-bloquants passant dans la circulation systémique soient faibles après instillation oculaire, le risque d''interactions médicamenteuses existe.', 'Il convient donc de tenir compte des interactions observées avec les bêta-bloquants administrés par voie générale.', 'Associations contre-indiquées', '+ Floctafénine', 'En cas de choc ou d''hypotension dus à la floctafénine, réduction des réactions cardiovasculaires de compensation par les bêta-bloquants.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Résumé du profil de tolérance', 'Lors des études cliniques, les effets indésirables les plus fréquemment rencontrés étaient une hyperhémie oculaire et une irritation de l’œil chez approximativement 5% et 2% des patients respectivemen', 'Description de certains effets indésirables', 'Comme d’autres médicaments ophtalmiques topiques, le timolol passe dans la circulation générale.', 'Cela peut entraîner des réactions indésirables semblables à celles des médicaments bêta-bloquants pris par voie systémique.', 'L’incidence des effets indésirables systémiques après une administration par voie ophtalmique reste plus faible qu’après administration systémique.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['La réponse de ces patients devra être étroitement surveillée.']);

  -- tertatolol (CIS 69859092)
  m := pg_temp.jp_matrice_by_norm('tertatolol');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : bêta-bloquant, non selectif, code ATC : C07AA16');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1', 'Asthme et bronchopneumopathies chroniques obstructives', 'Insuffisance cardiaque non contrôlée par le traitement', 'Choc cardiogénique', 'Blocs auriculo-ventriculaires des second et troisième degrés non appareillés', 'Angor de Prinzmetal', 'Maladie du sinus (y compris bloc sino-auriculaire)', 'Bradycardie (', 'Phénomène de Raynaud et troubles artériels périphériques', 'Phéochromocytome non traité', 'Hypotension', 'Insuffisance rénale très sévère (clairance de la créatinine inférieure à 10 ml/min, par précaution en l''absence d''études actuellement disponibles)']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Ne jamais interrompre brutalement le traitement chez les angineux : l''arrêt brusque peut entraîner des troubles du rythme graves, un infarctus du myocarde ou une mort subite.', 'Arrêt du traitement', 'Le traitement ne doit pas être interrompu brutalement, en particulier chez les patients présentant une cardiopathie ischémique.', 'La posologie doit être diminuée progressivement, c''est-à-dire idéalement sur une à deux semaines, en commençant en même temps, si nécessaire, le traitement substitutif, pour éviter une aggravation de l''angor.', 'Effets cardiovasculaires', '- Bradycardie : Si la fréquence s''abaisse au-dessous de 50-55 pulsations par minute au repos et que le patient présente des symptômes liés à la bradycardie, la posologie doit être diminuée (voir rubrique 4.2).', 'Une telle association ne doit se faire que sous surveillance clinique étroite et ECG, en particulier chez le sujet âgé ou en début de traitement (voir rubrique 4.5).', '- Association avec fingolimod : L’expérience est limitée chez les patients recevant un bêta-bloquant en association avec fingolimod.', 'L’utilisation concomitante d’un bêta-bloquant et de fingolimod peut être associée à une bradycardie sévère et à un bloc cardiaque.', 'En raison des effets additifs potentiels sur la fréquence cardiaque (fingolimod induit lors de son initiation un ralentissement de la fréquence cardiaque), l’association d’un bêta-bloquant au fingolimod est déconseillée.', 'Phéochromocytome', 'L''utilisation des bêta-bloquants dans le traitement de l''hypertension due au phéochromocytome traité nécessite une surveillance étroite de la pression artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées (voir rubrique 4.4) :', '+ Diltiazem', 'Troubles de l''automatisme (bradycardie excessive, arrêt sinusal), troubles de la conduction sino-auriculaire et auriculo-ventriculaire et défaillance cardiaque.', 'Une telle association ne doit se faire que sous surveillance clinique et ECG étroite, en particulier chez le sujet âgé ou en début de traitement.', '+ Fingolimod', 'Potentialisation des effets bradycardisants pouvant avoir des conséquences fatales.', 'Les bêta-bloquants sont d’autant plus à risque qu’ils empêchent les mécanismes de compensation adrénergique.', 'Surveillance clinique et ECG continu pendant les 24 heures suivant la première dose.', '+ Vérapamil', 'Troubles de l''automatisme (bradycardie excessive, arrêt sinusal), trouble de la conduction sino-auriculaire et auriculo-ventriculaire et défaillance cardiaque.', 'Une telle association ne doit se faire que sous surveillance clinique et ECG étroite, en particulier chez le sujet âgé ou en début de traitement', 'Associations faisant l''objet de précautions d''emploi :']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets ou évènements indésirables suivants ont été rapportés et sont classés en fonction de la fréquence suivante : très fréquent (³ 1/10) ; fréquent (³1/100, ³1/1000, ³1/10 000,', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Une telle association ne doit se faire que sous surveillance clinique étroite et ECG, en particulier chez le sujet âgé ou en début de traitement (voir rubrique 4.5).', 'L''utilisation des bêta-bloquants dans le traitement de l''hypertension due au phéochromocytome traité nécessite une surveillance étroite de la pression artérielle.']);

  -- piretanide (CIS 62715965)
  m := pg_temp.jp_matrice_by_norm('piretanide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : diurétiques de l’anse, code ATC : C03CA03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de l''hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Troubles hydro-électrolytiques (hyponatrémie sévère, hypokaliémie sévère),', 'Hypovolémie,', 'Déshydratation,', 'Etat pré-comateux et comateux associés à une encéphalopathie hépatique,', 'Insuffisance rénale sévère (clairance de la créatinine inférieure à 20 ml/min) ou insuffisance rénale avec anurie/oligoanurie,', 'Obstruction des voies urinaires,', 'Hypersensibilité aux sulfamides,', 'Allaitement.', 'En l’absence de données, le pirétanide est contre-indiqué chez l’enfant de moins de 15 ans ainsi que chez la femme enceinte.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Une surveillance étroite est particulièrement nécessaire chez les patients présentant :', 'Une hypotension,', 'Un diabète avéré ou latent (surveillance régulière de la glycémie),', 'Une goutte (surveillance régulière de l’uricémie),', 'Une obstruction partielle des voies urinaires (ex : hypertrophie prostatique, hydronéphrose, sténose urétrale),', 'Une cirrhose du foie avec insuffisance rénale,', 'Une hypoprotéinémie par exemple en cas de syndrome néphrotique,', 'Une sclérose cérébrale et/ou coronaire avancée,', 'Une altération de la perfusion cérébro-vasculaire,', 'Une maladie coronarienne.', 'La prise accidentelle de pirétanide peut entraîner une hypovolémie avec déshydratation (voir surdosage).']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Hypokaliémiants', 'L’hypokaliémie est un facteur favorisant l’apparition de troubles du rythme cardiaque (torsades de pointes notamment) et augmentant la toxicité de certains médicaments, par exemple la digoxine.', 'De ce fait, les médicaments qui peuvent entraîner une hypokaliémie sont impliqués dans un grand nombre d’interactions.', 'Il s’agit des diurétiques hypokaliémiants, seuls ou associés, des laxatifs stimulants, des glucocorticoïdes, du tétracosactide et de l’amphotéricine B (voie IV).', 'Hyponatrémiants', 'Certains médicaments sont plus fréquemment impliqués dans la survenue d’une hyponatrémie.', 'Ce sont les diurétiques, la desmopressine, les antidépresseurs inhibant la recapture de la sérotonine, la carbamazépine et l’oxcarbazépine.', 'L’association de ces médicaments majore le risque d’hyponatrémie.', 'Médicaments ototoxiques', 'L''utilisation conjointe de médicaments ayant une ototoxicité augmente le risque d’atteinte cochléo-vestibulaire.', 'Si une telle association est nécessaire, il convient de renforcer la surveillance de la fonction auditive.', 'Les médicaments concernés sont, notamment, les glycopeptides tels que vancomycine et teicoplanine, les aminosides, les organoplatines et les diurétiques de l’anse.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables du pirétanide sont listés ci-dessous.', 'Leur fréquence est indéterminée.', 'Affections hématologiques et du système lymphatique', 'thrombopénie, leucopénie, hémoconcentration', 'Troubles du métabolisme et de la nutrition', 'Affections du système nerveux']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Une surveillance étroite est particulièrement nécessaire chez les patients présentant :', 'Un diabète avéré ou latent (surveillance régulière de la glycémie),', 'Une goutte (surveillance régulière de l’uricémie),', 'La prise accidentelle de pirétanide peut entraîner une hypovolémie avec déshydratation (voir surdosage).']);

  -- bumetanide (CIS 68232635)
  m := pg_temp.jp_matrice_by_norm('bumetanide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : DIURETIQUE DE L''ANSE, code ATC : C03CA02 (C : Système cardiovasculaire).');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Oedèmes d’origine rénale et hépatique, chez l’adulte.', 'insuffisance cardiaque, chez l’adulte.', 'Pour l’utilisation chez la femme enceinte : (voir rubrique 4.6)']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit pas être utilisé dans les cas suivants :', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Déplétions électrolytiques sévères.', 'Anurie persistante.', 'Encéphalopathie hépatique, y compris coma.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Les patients doivent être informés des signes et symptômes du SSJ et du syndrome de Lyell et être étroitement surveillés à cet égard.', 'En cas d’apparition de signes et de symptômes évoquant l’une de ces réactions, la prise de bumétanide doit être interrompue et un traitement de remplacement doit être envisagé.', 'Si le patient a présenté une réaction grave au bumétanide telle que le SSJ ou un Lyell, le traitement ne doit plus jamais être administré à ce patient.', 'En cas d’administration du bumétanide chez des patients souffrant d''une atteinte hépatique sévère, la prudence est recommandée.', 'Chez des patients présentant une hypotension, le bumétanide doit être utilisé avec prudence.', 'Précautions d''emploi', 'Un déséquilibre hydroélectrolytique peut survenir (voir rubrique 4.8) et un traitement compensatoire doit être initié le cas échéant.', 'Un dosage régulier de la kaliémie doit être pratiqué.', 'Comme avec les autres diurétiques, le bumétanide peut entrainer une augmentation du taux d’acide urique dans le sang.', 'Chez les patients atteints d’un diabète sucré avéré ou latent, un dosage régulier de la glycémie et de la glycosurie doit être pratiqué.', 'Des cas d’hypomagnésémie ont été rapportés chez les patients traités par un inhibiteur de la pompe à protons.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations faisant l''objet de précautions d’emploi', '+ Lithium', 'Le bumétanide diminue la clairance du lithium entraînant une augmentation des taux de lithium dans le sang, par conséquent un traitement concomitant nécessite une surveillance stricte des taux de lithium dans le sang.', 'Une diminution des doses de lithium peut être nécessaire.', '+Glucosides digitaliques', 'L’hypokaliémie augmente la sensibilité aux glucosides digitaliques, ce qui peut provoquer une toxicité digitalique (nausées, vomissements et arythmies).', 'La kaliémie doit être contrôlée régulièrement et les signes d’une toxicité digitalique doivent être recherchés.', 'Une supplémentation en potassium et une réduction de la dose de glucoside digitalique doivent être envisagées le cas échéant.', '+ Inhibiteurs neuromusculaires non-dépolarisants', 'L’hypokaliémie augmente la sensibilité aux inhibiteurs neuromusculaires non-dépolarisants.', '+ Anti-arythmiques', 'Un contrôle régulier des taux d’électrolytes doit être pratiqué chez ces patients et les symptômes d’une arythmie doivent être recherchés.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Des réactions cutanées graves (SCAR), dont le syndrome de Stevens-Johnson (SSJ) et le syndrome de Lyell, ont été signalées en lien avec le bumétanide (voir rubrique 4.4).', 'Très fréquent (≥1/10)', 'Fréquent (≥1/100 et', 'Peu fréquent (≥1/1 000 et', 'Rare (≥1/10 000 et']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Les patients doivent être informés des signes et symptômes du SSJ et du syndrome de Lyell et être étroitement surveillés à cet égard.', 'Un dosage régulier de la kaliémie doit être pratiqué.', 'Chez les patients atteints d’un diabète sucré avéré ou latent, un dosage régulier de la glycémie et de la glycosurie doit être pratiqué.']);

  -- hydrochlorothiazide (CIS 64740636)
  m := pg_temp.jp_matrice_by_norm('hydrochlorothiazide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : diurétiques du segment cortical de dilution, code ATC : C03AA03');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['HYDROCHLOROTHIAZIDE ARROW 12,5 mg, comprimé sécable est indiqué chez les adultes dans le traitement des pathologies suivantes :', 'Œdèmes d''origine cardiaque ou rénale.', 'Œdèmes d''origine hépatique, le plus souvent en association avec un diurétique épargneur de potassium.', 'Hypertension artérielle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 ;', 'anurie ;', 'insuffisance rénale sévère (clairance de la créatinine inférieure à 30 ml/min).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Cancer de la peau non mélanome', 'Les actions photosensibilisantes de l’HCTZ pourraient constituer un mécanisme possible du CPNM.', 'Les patients prenant de l’HCTZ doivent être informés du risque de CPNM et être invités à vérifier régulièrement leur peau pour détecter toute nouvelle lésion et à signaler rapidement toute lésion cutanée suspecte.', 'Les lésions cutanées suspectes doivent être examinées rapidement, y compris éventuellement par un examen histologique des biopsies.', 'L''utilisation d’HCTZ peut également devoir être reconsidérée chez les patients ayant déjà présenté un CPNM (voir aussi rubrique 4.8).', 'Toxicité respiratoire aiguë', 'De très rares cas graves de toxicité respiratoire aiguë, notamment de syndrome de détresse respiratoire aiguë (SDRA), ont été rapportés après la prise d’hydrochlorothiazide.', 'L’œdème pulmonaire se développe généralement quelques minutes à quelques heures après la prise d’hydrochlorothiazide.', 'Au début, les symptômes comportent dyspnée, fièvre, détérioration pulmonaire et hypotension.', 'Si un diagnostic de SDRA est suspecté, HYDROCHLOROTHIAZIDE ARROW doit être retiré et un traitement approprié doit être administré.', 'L’hydrochlorothiazide ne doit pas être administré à des patients ayant déjà présenté un SDRA à la suite d’une prise d’hydrochlorothiazide.', 'Mises en garde spéciales']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L’administration concomitante d’HYDROCHLOROTHIAZIDE ARROW avec les médicaments suivants peut entraîner des interactions.', 'Médicaments hypokaliémiants', 'L’hypokaliémie est un facteur favorisant l’apparition de troubles du rythme cardiaque (torsades de pointes, notamment) et augmentant la toxicité de certains médicaments, par exemple la digoxine.', 'De ce fait, les médicaments qui peuvent entraîner une hypokaliémie sont impliqués dans un grand nombre d’interactions.', 'Il s’agit des diurétiques hypokaliémiants, seuls ou associés, des laxatifs stimulants, des glucocorticoïdes, du tétracosactide et de l’amphotéricine B (voie IV).', 'Médicaments hyponatrémiants', 'Certains médicaments sont plus fréquemment impliqués dans la survenue d’une hyponatrémie.', 'Ce sont les diurétiques, la desmopressine, les antidépresseurs inhibant la recapture de la sérotonine, la carbamazépine et l’oxcarbazépine.', 'L’association de ces médicaments majore le risque d’hyponatrémie.', 'Associations déconseillées', '+ Lithium', 'Augmentation de la lithémie avec signes de surdosage en lithium, comme lors d’un régime désodé (diminution de l’excrétion rénale du lithium).']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les évènements indésirables (Tableau 1) sont classés par fréquence, en commençant par les plus fréquents selon la convention suivante : très fréquent (> 1/10) ; fréquent (> 1/100, 1/1000, 1/10 000,', 'Tumeurs bénignes, malignes et non précisées (y compris kystes et polypes)', 'Thrombocytopénie (parfois avec purpura)', 'Insuffisance médullaire, anémie hémolytique, leucopénie, agranulocytose', 'Aplasie médullaire']);

  -- indapamide (CIS 60342439)
  m := pg_temp.jp_matrice_by_norm('indapamide');
